/**
 * The app-theme `<head>` block, generated: the `theme-color` meta(s) and the
 * script that puts the theme on `<html>` before first paint.
 *
 * Generated by the `app-theme-prepaint` Vite plugin from `theme.ts` and the
 * colour tokens, exactly as the board pre-paint is generated from
 * `boardThemes.ts`. Without it a visitor whose theme differs from the CSS
 * default would see one frame of the wrong theme on every page load.
 *
 * TWO MODES. With theme choice off (production until F3), the page is always
 * dark: one `theme-color` meta and a script that sets dark without reading
 * storage. With it on (the dev server now, everyone from F3), one meta per
 * system scheme as the no-JavaScript default, and a script that reads the
 * stored preference, resolves `system` against the operating system, and then
 * writes the resolved colour into every meta.
 */
import {
  DEFAULT_PREFERENCE,
  THEME_STORAGE_KEY,
  themeColor,
} from './themeCore';

export const APP_THEME_PREPAINT_MARKER = '<!-- app-theme-prepaint -->';

export function appThemeHead(choiceEnabled: boolean): string {
  const dark = themeColor('dark');
  const light = themeColor('light');

  if (!choiceEnabled) {
    return `<meta name="theme-color" content="${dark}" />
    <script>
    (function(){
      var r=document.documentElement;
      r.setAttribute('data-theme','dark');
      r.setAttribute('data-theme-preference','dark');
      r.style.colorScheme='dark';
    })();
    </script>`;
  }

  const key = JSON.stringify(THEME_STORAGE_KEY);
  const fallback = JSON.stringify(DEFAULT_PREFERENCE);
  return `<meta name="theme-color" media="(prefers-color-scheme: dark)" content="${dark}" />
    <meta name="theme-color" media="(prefers-color-scheme: light)" content="${light}" />
    <script>
    (function(){
      var p=null;try{p=localStorage.getItem(${key});}catch(e){}
      if(p!=='light'&&p!=='dark'&&p!=='system')p=${fallback};
      var d=false;try{d=matchMedia('(prefers-color-scheme: dark)').matches;}catch(e){}
      var t=p==='system'?(d?'dark':'light'):p;
      var r=document.documentElement;
      r.setAttribute('data-theme',t);
      r.setAttribute('data-theme-preference',p);
      r.style.colorScheme=t;
      var c=t==='dark'?${JSON.stringify(dark)}:${JSON.stringify(light)};
      var m=document.querySelectorAll('meta[name="theme-color"]');
      for(var i=0;i<m.length;i++)m[i].setAttribute('content',c);
    })();
    </script>`;
}
